import {escapeXML as E} from './text-editor.js';
export const MASKS={rectangle:'M0 0H1V1H0Z',shield:'M0 0H1V.72L.5 1 0 .72Z',diamond:'M.5 0 1 .5 .5 1 0 .5Z',arch:'M0 1V.3C0-.1 1-.1 1 .3V1Z'};
export function renderImage(b,src,doc){if(!src)return '';const id='img-'+b.id.replace(/[^a-z0-9-]/gi,''),a=b.imageAdjust||{},crop=b.crop||{x:0,y:0,w:1,h:1},zoom=Math.max(.1,Number(b.imageZoom)||1),offsetX=Number(b.imageX)||0,offsetY=Number(b.imageY)||0,mask=b.mask||'rectangle',fade=Number(b.fade)||0,w=b.w,h=b.h;let shape=mask==='circle'?`<circle cx="${w/2}" cy="${h/2}" r="${Math.min(w,h)/2}"/>`:mask==='ellipse'?`<ellipse cx="${w/2}" cy="${h/2}" rx="${w/2}" ry="${h/2}"/>`:`<path d="${MASKS[mask]||MASKS.rectangle}" transform="scale(${w},${h})"/>`;const bright=Number(a.brightness??100)/100,contrast=Number(a.contrast??100)/100,saturation=Number(a.saturation??100)/100,temperature=Number(a.temperature||0)/200,grey=Number(a.grayscale||0)/100;return `<defs><clipPath id="${id}-clip">${shape}</clipPath><linearGradient id="${id}-gradient" x1="0" y1="0" x2="0" y2="1"><stop offset="${Math.max(0,1-fade)}" stop-color="white"/><stop offset="1" stop-color="${fade?'black':'white'}"/></linearGradient><filter id="${id}-soft"><feGaussianBlur stdDeviation="${Number(b.softness)||0}"/></filter><mask id="${id}-mask"><rect width="${w}" height="${h}" fill="url(#${id}-gradient)" filter="url(#${id}-soft)"/></mask><filter id="${id}-adjust" color-interpolation-filters="sRGB"><feColorMatrix type="saturate" values="${saturation*(1-grey)}"/><feComponentTransfer><feFuncR type="linear" slope="${bright*contrast*(1+temperature)}" intercept="${.5*(1-contrast)}"/><feFuncG type="linear" slope="${bright*contrast}" intercept="${.5*(1-contrast)}"/><feFuncB type="linear" slope="${bright*contrast*(1-temperature)}" intercept="${.5*(1-contrast)}"/></feComponentTransfer></filter></defs><g clip-path="url(#${id}-clip)" mask="url(#${id}-mask)"><svg width="${w}" height="${h}" viewBox="${crop.x*w} ${crop.y*h} ${crop.w*w} ${crop.h*h}" preserveAspectRatio="none" overflow="hidden"><image href="${E(src)}" x="${w*(1-zoom)/2+offsetX}" y="${h*(1-zoom)/2+offsetY}" width="${w*zoom}" height="${h*zoom}" preserveAspectRatio="${(b.fit||doc.imageFit)==='cover'?'xMidYMid slice':'xMidYMid meet'}" filter="url(#${id}-adjust)"/></svg></g>`;}
export function installImages(E){let internal=null;document.querySelector('#sheet').addEventListener('pointerdown',e=>{const b=E.getBlock();if(!b?.editImage||!['portrait','image'].includes(b.type)||b.locked||E.mode!=='edit'||!e.target.closest(`[data-block="${b.id}"]`))return;e.stopImmediatePropagation();e.preventDefault();internal={b,startX:e.clientX,startY:e.clientY,x:b.imageX||0,y:b.imageY||0,before:E.snapshot()};},true);window.addEventListener('pointermove',e=>{if(!internal)return;internal.b.imageX=internal.x+(e.clientX-internal.startX)/E.scale;internal.b.imageY=internal.y+(e.clientY-internal.startY)/E.scale;E.draw();});window.addEventListener('pointerup',()=>{if(internal){E.record(internal.before);E.save();E.inspector();internal=null;}});return {reset:()=>{const b=E.getBlock();if(b)E.change(()=>{for(const key of ['imageX','imageY','imageZoom','crop','mask','fade','softness','imageAdjust'])delete b[key];},true,true);}};}
